local({
  s <- as.numeric(X_SESL_I)
  s[s == -9] <- NA
  w <- as.numeric(round)
  lo <- stats::ave(s, w, FUN = function(v) {
    if (all(is.na(v))) NA_real_ else stats::quantile(v, 0.4, na.rm = TRUE, names = FALSE)
  })
  hi <- stats::ave(s, w, FUN = function(v) {
    if (all(is.na(v))) NA_real_ else stats::quantile(v, 0.6, na.rm = TRUE, names = FALSE)
  })
  comp <- case_when(is.na(s) ~ NA_character_, s <= lo ~ "Low", s > hi ~ "High", .default = "Medium")
  pov <- recode_values(as.numeric(X_POVTY_I), 1 ~ "Low", 2 ~ "Medium", 3 ~ "High", default = NA_character_)
  coalesce(if_else(w == 7, pov, comp), "Unknown")
})

local({
  parent <- case_when(
    as.numeric(P_TVRUL3) == 1 | as.numeric(P_TVRUL2) == 1 ~ "TRUE",
    as.numeric(P_TVRUL3) == 2 & as.numeric(P_TVRUL2) == 2 ~ "FALSE",
    .default = NA_character_
  )
  child <- recode_values(as.numeric(C_RULWHN), 1 ~ "TRUE", 2 ~ "FALSE", default = NA_character_)
  if_else(as.numeric(round) == 2, parent, child)
})

local({
  items <- cbind(as.numeric(P_PTHARD), as.numeric(P_CHDBTH), as.numeric(P_SACRFC), as.numeric(P_FLANGR))
  items[!items %in% 1:4] <- NA
  items <- 4 - items
  rowSums(items) / 4
})

