local({
  n <- as.numeric(P_SPANK)
  case_when(n == 95 ~ "FALSE", n > 0 & n < 95 ~ "TRUE", n == 0 ~ "FALSE", .default = NA_character_)
})

local({
  spring_days <- recode_values(as.numeric(P_READBK), 1 ~ 0, 2 ~ 1.5, 3 ~ 4.5, 4 ~ 7, default = NA_real_)
  mins <- as.numeric(P_RDMINS)
  spring <- case_when(as.numeric(P_READBK) == 1 ~ 0, mins > 0 ~ mins * spring_days / 7 / 60, .default = NA_real_)
  if_else(as.numeric(round) == 4, spring, NA_real_)
})

